-- READ-ONLY metadata for the single owner-approved original33 release.
-- The existing runner enforces a read-only connection; no business rows or secrets.
select jsonb_build_object(
'frontier',(select max(version) from supabase_migrations.schema_migrations),
'count33',(select count(*) from supabase_migrations.schema_migrations where version='20271133000033'),
'name33',(select name from supabase_migrations.schema_migrations where version='20271133000033'),
'statements33',(select md5(array_to_string(statements,E'\n')) from supabase_migrations.schema_migrations where version='20271133000033'),
'ledger_without33',(select md5(jsonb_agg(jsonb_build_object('version',version,'name',name,'statements',statements) order by version)::text) from supabase_migrations.schema_migrations where version<>'20271133000033'),
'functions',coalesce((select functions from (select jsonb_agg(n.nspname||'.'||p.proname||'('||replace(oidvectortypes(p.proargtypes),' ','')||'):'||
md5(jsonb_build_object('source',replace(p.prosrc,E'\r\n',E'\n'),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'language',l.lanname,'returns',format_type(p.prorettype,null),'names',p.proargnames,'defaults',p.pronargdefaults,'strict',p.proisstrict,'leakproof',p.proleakproof,'volatility',p.provolatile,'parallel',p.proparallel)::text) order by n.nspname,p.proname) as functions from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.proname in ('automation_draft_scope','automation_draft_args','read_automation_draft','save_automation_draft')) f),'[]'::jsonb),
'dependencies',md5(jsonb_build_object(
'relations',(select jsonb_agg(jsonb_build_object('relation',c.oid::regclass::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'columns',(select jsonb_agg(jsonb_build_object('name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull) order by a.attnum) from pg_attribute a where a.attrelid=c.oid and a.attnum>0 and not a.attisdropped),'constraints',(select jsonb_agg(pg_get_constraintdef(k.oid) order by k.conname) from pg_constraint k where k.conrelid=c.oid)) order by c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname in ('tenants','profiles','tenant_members','paige_automations','paige_automation_acts','paige_workspace_events','paige_automation_triggers')),
'functions',(select jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'body_md5',md5(replace(p.prosrc,E'\r\n',E'\n')),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text) order by p.oid::regprocedure::text) from pg_proc p where p.oid in (to_regprocedure('public.current_user_tenant_id()'),to_regprocedure('public.record_capability_run(uuid,uuid,text,text,uuid,text,text,uuid,text,jsonb)'))))::text)) as contract;
